D.limitations = {"Visual meshes use finite tessellation (maximum centerline step 2 m); contact uses the original continuous runtime.","Texture stages beyond the recovered base/lightmap pass and original X-section seam triangulation are retained as descriptors; the exporter uses the recovered continuous surface for mesh geometry.","7 wall boundary sides cross different endpoint X-profile chords; shifted ground uses the original continuous query, while the native renderer boundary-transition compiler is not yet lifted.","4 authored wall faces contain nonfinite UV coordinates copied unchanged by rendserv 1001e530; raw bits retained, geometry exported with the original constant appearance colors and unused finite UVs because the original texture sampler result is undefined.","Visual state is a daytime race with full population, highest-detail LOD; source scene graphs preserve other authored branches. Dynamic flags and vehicles are not driven by game state. Original sky geometry/settings are retained in json/sky.json; sky and fog renderer effects are not installed.","Finite colour bake uses largest original MIP and bilinear sampling; Roblox regenerates mipmaps and performs its own lighting/filtering. It cannot reproduce every original view-dependent GPU sample bit for bit."}
D.chunks = {}
for i = 1, 30 do
    local part = require(script.Parent:WaitForChild("NR2003WatkinsGlenVisualDataPart" .. i))
    for _, fragment in ipairs(part) do
        local chunk = D.chunks[fragment.chunk]
        if not chunk then chunk = {geometries = {}}; D.chunks[fragment.chunk] = chunk end
        for key, value in pairs(fragment.header) do chunk[key] = value end
        for _, geometry in ipairs(fragment.geometries) do table.insert(chunk.geometries, geometry) end
    end
end
return D
